#!/usr/bin/env python3
"""Generate proven outbound request adaptations from one root parameter table."""
import argparse
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    config = json.loads((ROOT / 'upstream-request-adaptations.json').read_text())
    lines = [
        '// Code generated by tools/generate_upstream_request_adaptations.py; DO NOT EDIT.',
        'package service',
        '',
        'const openAIImageEditsMultipartDefault = ' + json.dumps(config['image_edits_multipart']['default']),
    ]
    lines += ['', 'var claudeOpus55LegacyThinking = map[string]claudeLegacyThinkingAdaptation{']
    for mode, rule in config['claude_opus55_legacy_thinking'].items():
        lines.append('\t' + json.dumps(mode) + ': {Type: ' + json.dumps(rule['type']) +
                     ', Effort: ' + json.dumps(rule['effort']) + '},')
    lines.append('}')
    output = subprocess.check_output(['gofmt'], input='\n'.join(lines) + '\n', text=True)
    # Migration 329 is a frozen upgrade snapshot, not a runtime host policy.
    hosts = ',\n'.join("      '" + host.replace("'", "''") + "'"
                      for host in config['image_edits_multipart']['migration_329_hosts'])
    migration = f'''-- Generated by tools/generate_upstream_request_adaptations.py.
-- Move the existing supplier compatibility into an explicit account capability.
-- Preserve operator choices; future URL changes do not change this capability.
UPDATE accounts
SET extra = COALESCE(extra, '{{}}'::jsonb) || '{{"image_edits_multipart": true}}'::jsonb,
    updated_at = NOW()
WHERE platform = 'openai'
  AND type = 'apikey'
  AND deleted_at IS NULL
  AND NOT (COALESCE(extra, '{{}}'::jsonb) ? 'image_edits_multipart')
  AND substring(lower(btrim(credentials ->> 'base_url')) FROM '^https?://([^/?#:]+)') IN (
{hosts}
  );
'''
    outputs = {
        ROOT / 'backend/internal/service/upstream_request_adaptations_gen_gotocc.go': output,
        ROOT / 'backend/migrations/329_openai_image_edits_account_format.sql': migration,
    }
    for destination, content in outputs.items():
        if args.check:
            if destination.read_text() != content:
                raise SystemExit(str(destination.relative_to(ROOT)) + ' is out of sync')
        else:
            destination.write_text(content)


if __name__ == '__main__':
    main()
